// baseline-file sha256:eeb0fdcc3f6c (generated by repo-setup; don't edit: re-run repo-setup to update)
// Fails unless every relative link in every tracked Markdown file points to a file or folder that
// exists, so moving or deleting a file can't leave docs pointing at nothing.
//
// Checks `[text](path)` and reference definitions `[ref]: path`. Skips external URLs (`https:`,
// `mailto:`, ...), same-page anchors (`#section`), fenced code blocks and inline code. For
// `file.md#section` only the file is checked.
//
// Templates link to files in the repo they will be copied into. List them, one path or folder per
// line (`#` starts a comment), in `.markdown-links-ignore` at the repo root, a file you own.
//
// Usage: node .baseline/checks/markdown-links.mjs   Run by CI on every PR.
import { execFileSync } from 'node:child_process';
import { existsSync, readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';

const root = execFileSync('git', ['rev-parse', '--show-toplevel'], { encoding: 'utf8' }).trim();
const IGNORE_FILE = join(root, '.markdown-links-ignore');
const ignored = existsSync(IGNORE_FILE)
  ? readFileSync(IGNORE_FILE, 'utf8').split('\n').map((line) => line.replace(/#.*/, '').trim().replace(/\/$/, '')).filter(Boolean)
  : [];
const isIgnored = (file) => ignored.some((path) => file === path || file.startsWith(`${path}/`));
const files = execFileSync('git', ['ls-files', '*.md'], { cwd: root, encoding: 'utf8' })
  .split('\n')
  .filter((file) => file && !isIgnored(file));

const INLINE = /\]\(\s*<?([^)\s>]+)>?(?:\s+(?:"[^"]*"|'[^']*'))?\s*\)/g;
const REFERENCE = /^ {0,3}\[[^\]]+\]:\s*<?(\S+?)>?(?:\s|$)/gm;

const broken = [];
for (const file of files) {
  const text = readFileSync(join(root, file), 'utf8').replace(/^(```|~~~)[\s\S]*?^\1/gm, '').replace(/`[^`\n]*`/g, '');
  for (const [, target] of [...text.matchAll(INLINE), ...text.matchAll(REFERENCE)]) {
    if (/^([a-z][a-z0-9+.-]*:|#)/i.test(target)) continue;
    const path = decodeURI(target.split('#')[0]);
    if (path && !existsSync(join(root, dirname(file), path))) broken.push(`${file}: ${target}`);
  }
}

if (broken.length) {
  console.error(`Links to files that don't exist:
${broken.map((b) => `  - ${b}`).join('\n')}

Point each at the file's new place, or remove the link.`);
  process.exit(1);
}
console.log(`${files.length} Markdown files: every relative link resolves.`);
